-- TheGreenFeed — survey submissions
--
-- Stores anonymous survey responses. Only the validated server-side route
-- handler may write to this table: Row Level Security is enabled and no
-- policies are created, so the public (anon / authenticated) roles cannot
-- SELECT, INSERT, UPDATE, or DELETE any rows. The secret-key client used by
-- the route handler bypasses RLS.
--
-- `id` and `created_at` are generated by the database; a browser-supplied
-- timestamp is never trusted.

create table if not exists public.survey_submissions (
  id uuid primary key default gen_random_uuid(),
  answers jsonb not null check (jsonb_typeof(answers) = 'object'),
  schema_version text not null default 'v1',
  created_at timestamptz not null default now()
);

-- The survey only records answers and the schema version. No names, email
-- addresses, accounts, or other personal-data columns are collected.

comment on table public.survey_submissions is
  'Anonymous survey responses. Writes happen only through the validated server route. RLS is enabled with no public policies, so anon/authenticated roles have no access.';

-- Enable Row Level Security. With no policies attached, every operation by
-- anon and authenticated roles is denied.
alter table public.survey_submissions enable row level security;

-- Belt and braces: Supabase default privileges may grant table privileges to
-- the public roles on creation. Revoke them explicitly so the publishable-key
-- client can never read or write responses even if RLS were misconfigured.
revoke all on public.survey_submissions from anon, authenticated;
